#include <nlohmann/json.hpp>
#include <iostream>

int main() {
    try {
        nlohmann::ordered_json j = nlohmann::ordered_json::object();
        std::string short_key = "/0/a";
        std::string long_key = "/";
        for(int i=0; i<10; ++i) long_key += "1234567890/";
        long_key += "0/b";
        j[short_key] = 1;
        j[long_key] = 2;
        auto unflattened = j.unflatten();
        std::cout << unflattened.dump() << std::endl;
    } catch (const std::exception& e) {
        std::cout << "Exception: " << e.what() << std::endl;
    }
    return 0;
}
